async function main() {
  console.log("📰 IMPORTAÇÃO DE ARTIGOS BPR\n");
  console.log("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n");

  const author = await prisma.user.findFirst({
    where: { role: { in: ["SUPERADMIN", "ADMIN"] } },
    orderBy: { createdAt: "asc" },
  });

  if (!author) {
    console.error("❌ Nenhum utilizador ADMIN/SUPERADMIN encontrado — abortando.");
    process.exit(1);
  }

  console.log(`✍️  Autor: ${author.firstName || ""} ${author.lastName || ""} (${author.id})\n`);

  let created = 0;
  let skipped = 0;

  for (const a of ARTICLES) {
    const baseSlug = slugify(a.titleEn);
    const existing = await prisma.article.findUnique({ where: { slug: baseSlug } });

    if (existing) {
      console.log(`⏭️  Já existe, a saltar: "${a.titleEn}" (slug: ${baseSlug})`);
      skipped++;
      continue;
    }

    await prisma.article.create({
      data: {
        title: a.titleEn,
        slug: baseSlug,
        excerpt: a.excerptEn,
        content: a.contentEn,
        titleEn: a.titleEn,
        excerptEn: a.excerptEn,
        contentEn: a.contentEn,
        titlePt: a.titlePt,
        excerptPt: a.excerptPt,
        contentPt: a.contentPt,
        publishLanguage: "en",
        language: "en",
        imageUrl: null,
        published: false,
        authorId: author.id,
        tags: a.tags,
        keyword: a.keyword,
        metaDescription: a.metaDescription,
      },
    });

    console.log(`✅ Criado como rascunho: "${a.titleEn}" (slug: ${baseSlug})`);
    created++;
  }

  console.log("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
  console.log(`✅ Criados: ${created}  |  ⏭️  Já existiam: ${skipped}  |  Total: ${ARTICLES.length}`);
  console.log("Todos ficam como DRAFT (published: false) — adiciona imagens e publica manualmente no admin.");
}

main()
  .catch((e) => {
    console.error("❌ Erro:", e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
